export function sigilSvg(key,color='currentColor',attributes=''){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" ${attributes} role="img" aria-label="${sigils[key]?.name||'Sun'} sigil"><path d="${sigilPaths[key]||sigilPaths.sun}" fill="none" stroke="${color}" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/></svg>`}
export function shrineHeight(x,z){const r=Math.hypot(x,z);return r<=.65?1.005:r<=.95?.88:r<=1.55?.66:r<=2?.43:.19}
